function add() {
    return left() + right();
}

function subtract() {
    return left() - right();
}

function multiply() {
    return left() * right();
}

function divide() {
    return left() / right();
}

function remainder() {
    return left() % right();
}

function less() {
    return left() < right();
}

function greater() {
    return left() > right();
}

function lessEqual() {
    return left() <= right();
}

function greaterEqual() {
    return left() >= right();
}
